// ───────────────────────── 템플릿 색 바꾸기 ─────────────────────────
const THEMES = [["", "원래 색"], ["pink", "분홍", 345], ["sky", "하늘", 205], ["mint", "민트", 155], ["lavender", "라벤더", 265],
  ["lemon", "레몬", 48], ["beige", "베이지", 32], ["gray", "회색"], ["navy", "남색", 226]];
function rgbToHsl(r, g, b) {
  r /= 255; g /= 255; b /= 255;
  const mx = Math.max(r, g, b), mn = Math.min(r, g, b), l = (mx + mn) / 2;
  if (mx === mn) return [0, 0, l];
  const d = mx - mn, s = l > 0.5 ? d / (2 - mx - mn) : d / (mx + mn);
  const hh = mx === r ? (g - b) / d + (g < b ? 6 : 0) : mx === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return [hh * 60, s, l];
}
function hslToRgb(hh, s, l) {
  const f = (n) => { const k = (n + hh / 30) % 12, a = s * Math.min(l, 1 - l); return Math.round(255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1)))); };
  return [f(0), f(8), f(4)];
}
function themeColor(col, th) {
  const t = THEMES.find((x) => x[0] === th);
  if (!t || !th) return col;
  let r, g, b, a = null, m;
  if ((m = /^#([0-9a-f]{6})$/i.exec(col))) { const n = parseInt(m[1], 16); r = n >> 16; g = (n >> 8) & 255; b = n & 255; }
  else if ((m = /^rgba?\(([^)]*)\)$/i.exec(col))) { const p = m[1].split(",").map((x) => parseFloat(x)); [r, g, b] = p; a = p[3] ?? null; }
  else return col;
  let [hh, s, l] = rgbToHsl(r, g, b);
  if (th === "gray") s = Math.min(s, 0.04);
  else if (s >= 0.06 || (r === 255 && g === 255 && b === 255)) {
    if (!(r === 255 && g === 255 && b === 255)) {
      hh = t[2];
      if (th === "beige") s = Math.min(s, 0.4);
    }
  }
  const [R, G, B] = hslToRgb(hh, s, l);
  if (a != null) return `rgba(${R},${G},${B},${a})`;
  return "#" + [R, G, B].map((v) => v.toString(16).padStart(2, "0")).join("");
}
const recolorStr = (str, th) => str.replace(/#[0-9a-f]{6}\b|rgba?\([^)]*\)/gi, (m) => themeColor(m, th));
const themedCache = new Map();
function themed(tpl, th) {
  if (!tpl || !th) return tpl;
  const key = tpl.id + "|" + th;
  if (themedCache.has(key)) return themedCache.get(key);
  const walk = (v, k) => {
    if (k === "decos") return v;
    if (typeof v === "string") return recolorStr(v, th);
    if (Array.isArray(v)) return v.map((x) => walk(x));
    if (typeof v === "function") return v;
    if (v && typeof v === "object") return Object.fromEntries(Object.entries(v).map(([kk, vv]) => [kk, walk(vv, kk)]));
    return v;
  };
  const out = walk(tpl);
  out.id = tpl.id; out.name = tpl.name;
  if (tpl.outerImg) out.outerImg = () => tpl.outerImg((c) => themeColor(c, th));
  themedCache.set(key, out);
  return out;
}
const TPL_RENAMED = { "wine-note": "navy-note" };
